import styled from '@emotion/styled';

export const AISummaryVolumePagesStyles = {
  Container: styled.div`
    display: flex;
    flex-direction: column;
    gap: 16px;
    width: 100%;
  `,
  Title: styled.div`
    font-family: Barlow;
    display: flex;
    align-items: center;
    gap: 8px;
    padding-left: 8px;
    h1 {
      margin: 0;
    }
  `,
  Body: styled.div`
    padding: 0 8px;
  `,
  SectionIndicator: styled.p`
    margin: 3px 0 2px 0;
    font-family: Work Sans;
    font-weight: 600;
    font-size: 14px;
    color: #67665f;
  `,
  Empty: styled.div`
    background-color: #fff;
    padding: 16px;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: center;
    justify-content: center;
    height: 938px;
  `,
};

export const AISummaryVolumePagesSkeletonStyles = {
  Container: styled.div`
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding: 0 8px;
  `,

  Grid: styled.div`
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-auto-rows: auto;
    column-gap: 16px;
    row-gap: 8px;
  `,

  Bullets: styled.div`
    grid-column: 1 / -1;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    gap: 8px;
  `,

  Megabrands: styled.div`
    grid-area: 2 / 1 / 4 / 3;
    min-width: 0;
  `,

  Sustain: styled.div`
    grid-area: 4 / 1 / 6 / 3;
    min-width: 0;
  `,

  SuperiorCore: styled.div`
    grid-area: 2 / 3 / 3 / 5;
    min-width: 0;
  `,

  LeadPremium: styled.div`
    grid-area: 3 / 3 / 4 / 5;
    min-width: 0;
  `,

  BeyondBeer: styled.div`
    grid-area: 4 / 3 / 5 / 5;
    min-width: 0;
  `,

  BalancedChoices: styled.div`
    grid-area: 5 / 3 / 6 / 5;
    min-width: 0;
  `,
};

export const GradientTextSVGStyles = {
  Svg: styled.svg`
    display: block;
    margin-bottom: 24px;
  `,
};
